"use client";

import { useEffect, useRef } from "react";
import PersonaLane from "./persona-lane";
import TerminalCast, { type TerminalLine } from "./terminal-cast";
import { resolveCover } from "@/lib/covers";
import { prefersReducedMotion } from "@/lib/theme";

/**
 * PinnedReplay — the 7-step scroll walkthrough of one real run, ported
 * verbatim from the POC: a tall track pins a rail + stage; scroll advances
 * discrete steps; rail items are clickable; a 420ms idle-snap centers the
 * nearest step (cancelled by any fresh input; disabled for reduced motion);
 * lane covers resolve as their step activates. Below 1024px — or without
 * JS — CSS stacks the panels as a readable list and covers resolve via IO.
 */

// Injected as HTML for its token spans — keep it a literal, never
// interpolate untrusted text into it.
const BRIEF_YAML = `<span class="cy">run:</span> <span class="cv">cua-2026-08-07T17-44-48-760Z-87389419</span>
<span class="cy">date:</span> <span class="cv">2026-08-07</span>
<span class="cy">subject:</span>
  <span class="cc"># open-source virtual whiteboard</span>
  <span class="cy">app:</span> <span class="cv">Excalidraw</span>
  <span class="cy">clone:</span> <span class="cv">excalidraw/excalidraw · commit-pinned</span>
<span class="cy">desktop:</span> <span class="cv">hosted sandbox · 1920×1080</span>
<span class="cy">lanes:</span>
  - <span class="ca">01</span> <span class="cv">diagram-login-flow</span>
  - <span class="ca">02</span> <span class="cv">sticky-notes</span>
  - <span class="ca">03</span> <span class="cv">sketch-shapes</span>
  - <span class="ca">04</span> <span class="cv">export-drawing</span>`;

const RAIL_ITEMS: Array<[string, string, string, boolean?]> = [
  ["00", "Brief", "the lab, in YAML"],
  ["01", "Lane 01", "diagram-login-flow"],
  ["02", "Lane 02", "sticky-notes"],
  ["03", "Lane 03", "sketch-shapes · gave up", true],
  ["04", "Lane 04", "export-drawing"],
  ["05", "Bundle", "what landed in .humanish/"],
  ["06", "Verify", "16/16 checks"]
];

const VERIFY_CAST: TerminalLine[] = [
  { kind: "cmd", text: "$ humanish verify" },
  { kind: "ok", text: "redaction passed" },
  { kind: "ok", text: "actor engagement: live actor traces that claim goal_satisfied carry at least one action or message" },
  { kind: "ok", text: "actor verdict consistency: live pass verdicts do not hide failed, blocked, or timed-out actor traces" },
  { kind: "dim", text: "… 13 more checks" },
  { kind: "sum", text: "16/16 passed → status: local_only", note: "(RAW_SCREENSHOTS)" }
];

const LANES: Array<{
  idx: string;
  name: string;
  img: string;
  alt: string;
  reportLabel: string;
  report: string;
  passed: boolean;
}> = [
  {
    idx: "01",
    name: "diagram-login-flow",
    img: "/study/excalidraw-lane1.jpg",
    alt: "Keyframe from lane diagram-login-flow: the Excalidraw canvas on the sandbox desktop with two rectangles labeled Login and Dashboard connected by an arrow",
    reportLabel: "Final report — verbatim",
    report: "Done",
    passed: true
  },
  {
    idx: "02",
    name: "sticky-notes",
    img: "/study/excalidraw-lane2.jpg",
    alt: "Keyframe from lane sticky-notes: the Excalidraw canvas on the sandbox desktop with three colored to-do notes — Draft plan, Call team, Buy supplies",
    reportLabel: "Final report — verbatim",
    report: "Done.",
    passed: true
  },
  {
    idx: "03",
    name: "sketch-shapes",
    img: "/study/excalidraw-lane3.jpg",
    alt: "Keyframe from lane sketch-shapes: the Excalidraw canvas on the sandbox desktop with an ellipse, a rectangle, stray line strokes, and the freehand tool panel open — the lane gave up here",
    reportLabel: "Recorded reason — verbatim",
    report: "gave up: 8 consecutive turns with no change to the UI state",
    passed: false
  },
  {
    idx: "04",
    name: "export-drawing",
    img: "/study/excalidraw-lane4.jpg",
    alt: "Keyframe from lane export-drawing: the Excalidraw canvas on the sandbox desktop with a single large rectangle, deselected after the export flow",
    reportLabel: "Final report — verbatim",
    report: "Done",
    passed: true
  }
];

export default function PinnedReplay() {
  const trackRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const track = trackRef.current;
    if (!track) return;

    // The pinned desktop layout is CSS-gated on html.js. humanish.dev sets it
    // pre-paint in the layout; adding it here too makes the block
    // self-sufficient when installed elsewhere.
    document.documentElement.classList.add("js");

    const rm = prefersReducedMotion();
    const mqDesk = window.matchMedia("(min-width:1024px)");
    const hasIO = "IntersectionObserver" in window;

    const panels = Array.from(track.querySelectorAll<HTMLElement>(".panel"));
    const ritems = Array.from(track.querySelectorAll<HTMLButtonElement>(".ritem"));
    const fill = track.querySelector<HTMLElement>("#pf");
    const N = panels.length;
    let idx = -1;
    let snapT: ReturnType<typeof setTimeout> | null = null;
    let ticking = false;

    const metrics = () => {
      const r = track.getBoundingClientRect();
      const total = track.offsetHeight - window.innerHeight;
      const y = Math.min(Math.max(-r.top, 0), Math.max(total, 1));
      const abs = r.top + (window.scrollY || window.pageYOffset);
      return { y, total, abs };
    };
    const setStep = (i: number) => {
      if (i === idx) return;
      idx = i;
      panels.forEach((p, k) => {
        p.classList.toggle("on", k === i);
        p.classList.toggle("past", k < i);
      });
      ritems.forEach((b, k) => {
        b.classList.toggle("on", k === i);
        b.classList.toggle("done", k < i);
        if (k === i) {
          b.setAttribute("aria-current", "step");
        } else {
          b.removeAttribute("aria-current");
        }
      });
      const cv = panels[i]?.querySelector<HTMLCanvasElement>("canvas.cover");
      if (cv) resolveCover(cv, 220);
    };
    const queueSnap = () => {
      if (rm || !mqDesk.matches) return;
      if (snapT) clearTimeout(snapT);
      snapT = setTimeout(() => {
        const m = metrics();
        if (m.total <= 0 || m.y <= 0 || m.y >= m.total) return;
        const step = m.total / N;
        const center = (Math.min(N - 1, Math.floor((m.y / m.total) * N)) + 0.5) * step;
        const delta = center - m.y;
        if (Math.abs(delta) > 8 && Math.abs(delta) < step * 0.46) {
          window.scrollTo({ top: m.abs + center, behavior: "smooth" });
        }
      }, 420);
    };
    const update = () => {
      if (!mqDesk.matches) return;
      const m = metrics();
      if (m.total <= 0) return;
      const p = m.y / m.total;
      setStep(Math.min(N - 1, Math.floor(p * N)));
      if (fill) fill.style.transform = `scaleY(${p})`;
      queueSnap();
    };
    const toStep = (k: number) => {
      const m = metrics();
      if (m.total <= 0) return;
      const step = m.total / N;
      window.scrollTo({ top: m.abs + (k + 0.5) * step, behavior: rm ? "auto" : "smooth" });
    };

    const onRailClick = (e: Event) => {
      const b = e.currentTarget as HTMLButtonElement;
      toStep(parseInt(b.getAttribute("data-i") || "0", 10));
    };
    ritems.forEach((b) => b.addEventListener("click", onRailClick));

    const onScroll = () => {
      if (!ticking) {
        ticking = true;
        requestAnimationFrame(() => {
          ticking = false;
          update();
        });
      }
    };
    const onResize = () => update();
    const cancelSnap = () => {
      if (snapT) clearTimeout(snapT);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onResize, { passive: true });
    const cancelEvents = ["wheel", "touchstart", "pointerdown", "keydown"] as const;
    cancelEvents.forEach((ev) => window.addEventListener(ev, cancelSnap, { passive: true }));

    setStep(0);
    update();

    let cio: IntersectionObserver | null = null;
    if (!mqDesk.matches && hasIO) {
      cio = new IntersectionObserver(
        (es) => {
          es.forEach((en) => {
            if (!en.isIntersecting) return;
            resolveCover(en.target.querySelector<HTMLCanvasElement>("canvas.cover"), 260);
            cio?.unobserve(en.target);
          });
        },
        { threshold: 0.35 }
      );
      panels.forEach((p) => {
        if (p.querySelector("canvas.cover")) cio?.observe(p);
      });
    }

    return () => {
      if (snapT) clearTimeout(snapT);
      ritems.forEach((b) => b.removeEventListener("click", onRailClick));
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onResize);
      cancelEvents.forEach((ev) => window.removeEventListener(ev, cancelSnap));
      cio?.disconnect();
    };
  }, []);

  return (
    <div className="wt-track" id="runtrack" ref={trackRef}>
      <div className="wt-sticky">
        <p className="runband" aria-hidden="true"><span>Run <b>cua-2026-08-07T17-44-48-760Z-87389419</b> · 2026-08-07</span><span>3/4 lanes passed · verify 16/16 checks</span></p>
        <nav className="rail" aria-label="Run steps">
          <span className="rail-k">Replay · one real run</span>
          <span className="rtrack" aria-hidden="true"><i id="pf"></i></span>
          {RAIL_ITEMS.map(([ridx, b, i, fail], k) => (
            <button className={fail ? "ritem ritem-fail" : "ritem"} data-i={k} key={ridx}>
              <span className="ridx">{ridx}</span>
              <span className="rtx"><b>{b}</b><i>{i}</i></span>
            </button>
          ))}
        </nav>

        <div className="stage">
          <article className="panel" data-i="0">
            <header className="pbar"><span className="pl"><b className="pidx">00</b><span className="pname">brief · the lab</span></span><span className="pr">lab.yaml</span></header>
            <div className="pbody pbody-brief">
              <dl className="brief-facts">
                <div><dt>Subject</dt><dd>Excalidraw</dd></div>
                <div><dt>Desktop</dt><dd>hosted · 1920×1080</dd></div>
                <div><dt>Lanes</dt><dd>4 · parallel</dd></div>
                <div><dt>Date</dt><dd>2026-08-07</dd></div>
              </dl>
              <pre className="code" dangerouslySetInnerHTML={{ __html: BRIEF_YAML }} />
            </div>
            <footer className="pcap"><p className="prep"><span className="plab">The lab</span>One YAML lab declares the persona, its four missions, and a commit-pinned Excalidraw clone. Each lane gets its own hosted 1920×1080 desktop.</p></footer>
          </article>

          {LANES.map((lane, i) => (
            <PersonaLane {...lane} dataI={i + 1} sizer={i === 0} key={lane.idx} />
          ))}

          <article className="panel" data-i="5">
            <header className="pbar"><span className="pl"><b className="pidx">05</b><span className="pname">bundle · evidence</span></span><span className="pr">.humanish/ · gitignored</span></header>
            <div className="pbody">
              <div className="ledger">
                <div className="lh">.humanish/runs/cua-2026-08-07T17-44-48-760Z-87389419<span>4 lanes</span></div>
                <div className="lrow"><span className="ln"><em>├</em>screenshots</span><span className="ld">every screenshot each lane saw · 28 frames</span></div>
                <div className="lrow"><span className="ln"><em>├</em>action traces</span><span className="ld">ordered, end to end</span></div>
                <div className="lrow"><span className="ln"><em>├</em>lifecycle events</span><span className="ld">launch to landing</span></div>
                <div className="lrow"><span className="ln"><em>├</em>estimated cost</span><span className="ld">~$1.54 · estimated (rates as of 2026-08-05)</span></div>
                <div className="lrow"><span className="ln"><em>└</em>wall-clock</span><span className="ld">6m 06s · run created → last lane landed</span></div>
              </div>
            </div>
            <footer className="pcap"><p className="prep"><span className="plab">Where it lands</span>The run lands in gitignored <code>.humanish/</code>: every screenshot each lane saw, ordered action traces, lifecycle events, and estimated cost at dated rates.</p></footer>
          </article>

          <article className="panel panel-dark" data-i="6">
            <header className="pbar"><span className="pl"><b className="pidx">06</b><span className="pname">verify · share-safety</span></span><span className="pr">fail-closed</span></header>
            <div className="pbody">
              <TerminalCast lines={VERIFY_CAST} />
            </div>
            <footer className="pcap"><p className="prep"><span className="plab">The gate</span><code>humanish verify</code> grades the bundle fail-closed. This run: 16/16 checks passed — and the bundle still grades <code>local_only</code>, because it holds full-fidelity screenshots. Publishing these crops was a reviewed, deliberate act.</p></footer>
          </article>
        </div>
      </div>
    </div>
  );
}

/* @humanish/pinned-replay — generated from app/globals.css by scripts/extract-registry-css.mjs.
   Do not edit by hand; edit globals.css and run `pnpm registry:build`.
   Assumes a reset that zeroes margins/padding and sets border-box
   (e.g. Tailwind Preflight); the spacing these components depend on is also
   pinned explicitly below. Colors come from the humanish token system
   (@humanish/humanish-tokens); fonts fall back to system stacks unless
   --font-newsreader / --font-geist / --font-geist-mono are provided. */

.chip {
  display: inline-flex; align-items: center; gap: 6px;
  font-family: var(--mono); font-size: 9.5px; font-weight: 500; letter-spacing: .14em;
  color: var(--accent-ink); border: 1px solid var(--accent-dim);
  padding: 3px 9px; border-radius: 999px; white-space: nowrap;
}

.chip-pass::before { content: "✓"; font-size: 10px
}

.chip-dot::before { content: ""; width: 5px; height: 5px; border-radius: 50%; background: var(--accent-ink)
}

.chip-mute { color: var(--muted); border-color: var(--line)
}

.chip-mute::before { background: var(--muted)
}

.whint { display: none
}

@media (min-width: 1024px) {
  html.js .whint {
      display: block; text-align: right; margin: 0 0 12px;
      font-family: var(--mono); font-size: 10.5px; font-weight: 500;
      letter-spacing: .15em; text-transform: uppercase; color: var(--label);
  }
}

.runband { display: none
}

@media (min-width: 1024px) {
  html.js .runband {
      margin: 0; position: absolute; top: 0; left: 0; right: 0;
      display: flex; justify-content: space-between; align-items: baseline; gap: 8px 24px; flex-wrap: wrap;
      padding: 20px 0 13px; border-bottom: 1px solid var(--line-soft);
      font-family: var(--mono); font-size: 10.5px; letter-spacing: .08em; color: var(--label);
  }
  html.js .runband b { font-weight: 500; color: var(--ink)
  }
}

.wt-track { position: relative
}

@media (min-width: 1024px) {
  html.js .wt-track { height: calc(7 * 84vh)
  }
}

.wt-sticky { display: grid; gap: 16px
}

@media (min-width: 1024px) {
  html.js .wt-sticky {
      position: sticky; top: 0; height: 100vh;
      grid-template-columns: 292px minmax(0, 1fr);
      gap: clamp(28px, 4vw, 60px); align-items: center; padding: 28px 0;
  }
  html:not(.js) .wt-sticky { grid-template-columns: minmax(0, 1fr); max-width: 880px; margin: 0 auto
  }
}

.rail { display: none
}

@media (min-width: 1024px) {
  html.js .rail { display: flex; flex-direction: column; gap: 4px; position: relative; padding-left: 26px
  }
}

.rail-k {
  font-family: var(--mono); font-size: 10px; font-weight: 500;
  letter-spacing: .16em; text-transform: uppercase; color: var(--label);
  padding: 0 14px 10px;
}

.rtrack { position: absolute; left: 0; top: 8px; bottom: 8px; width: 2px; background: var(--line); border-radius: 2px; overflow: hidden
}

.rtrack i { position: absolute; inset: 0; background: var(--accent-ink); transform: scaleY(0); transform-origin: top
}

.ritem {
  display: flex; align-items: baseline; gap: 12px; text-align: left;
  padding: 10px 14px; border-radius: 10px; border: 1px solid transparent;
  color: var(--muted); font: inherit; background: none; cursor: pointer;
  transition: background .18s, color .18s, border-color .18s, box-shadow .18s;
}

.ritem .ridx { font-family: var(--mono); font-size: 11.5px; font-weight: 500; letter-spacing: .08em; width: 26px; flex: none; color: var(--muted)
}

.ritem .rtx b { display: block; font-size: 14.5px; font-weight: 600; letter-spacing: -.01em; color: var(--body-c); transition: color .18s
}

.ritem .rtx i { display: block; font-style: normal; font-family: var(--mono); font-size: 10.5px; color: var(--muted); margin-top: 2px
}

.ritem:hover { background: var(--rail-hover)
}

.ritem.on { background: var(--rail-on); border-color: var(--line); box-shadow: var(--sh-rail)
}

.ritem.on .rtx b { color: var(--ink)
}

.ritem.on .ridx { color: var(--accent-ink)
}

.ritem.done .ridx { color: var(--accent-ink)
}

.ritem.done .rtx b::after { content: " ✓"; color: var(--accent-ink); font-size: 12px
}

.ritem.ritem-fail.done .ridx { color: var(--muted)
}

.ritem.ritem-fail.done .rtx b::after { content: ""
}

.stage { position: relative
}

@media (min-width: 1024px) {
  html.js .stage { max-width: min(100%, calc((100vh - 168px) * 1.845))
  }
}

.panel {
  display: flex; flex-direction: column;
  background: var(--panel); border: 1px solid var(--line); border-radius: 16px; overflow: hidden;
  box-shadow: var(--sh-panel);
}

.pbar {
  display: flex; justify-content: space-between; align-items: center; gap: 12px;
  min-height: 40px; padding: 8px 16px; border-bottom: 1px solid var(--line-soft);
  background: var(--accent-wash);
}

.pl { display: flex; align-items: baseline; gap: 11px; min-width: 0
}

.pidx { font-family: var(--mono); font-size: 11px; font-weight: 500; color: var(--accent-ink); letter-spacing: .08em
}

.pname { font-family: var(--mono); font-size: 11px; color: var(--ink); letter-spacing: .09em; text-transform: uppercase; overflow: hidden; text-overflow: ellipsis; white-space: nowrap
}

.pr { font-family: var(--mono); font-size: 10.5px; color: var(--label); letter-spacing: .08em; text-transform: uppercase; white-space: nowrap
}

.pbody { flex: 1; display: flex; align-items: center; justify-content: center; padding: 26px 20px
}

@media (min-width: 1024px) {
  .pbody { padding: 30px
  }
}

.pcap {
  display: flex; justify-content: space-between; align-items: center; gap: 14px;
  min-height: 52px; padding: 12px 16px; border-top: 1px solid var(--line-soft);
}

.prep { margin: 0; min-width: 0; font-size: 13px; color: var(--body-c)
}

.plab { display: block; font-family: var(--mono); font-size: 9.5px; letter-spacing: .15em; text-transform: uppercase; color: var(--label); margin-bottom: 3px
}

.prep q { font-family: var(--mono); font-size: 12.5px; color: var(--ink); quotes: "\201C" "\201D"
}

.prep code { font-size: .92em
}

.pbody-brief { flex-direction: column; align-items: stretch; justify-content: flex-start; gap: 22px
}

.brief-facts { display: flex; flex-wrap: wrap; row-gap: 10px; border-bottom: 1px solid var(--line-soft); padding-bottom: 12px
}

.brief-facts div { display: grid; gap: 3px; align-content: start; padding-right: 16px; margin-right: 16px; border-right: 1px solid var(--line-soft)
}

.brief-facts div:last-child { border-right: 0; margin-right: 0; padding-right: 0
}

.brief-facts dt { margin: 0; font-family: var(--mono); font-size: 9.5px; letter-spacing: .14em; text-transform: uppercase; color: var(--label)
}

.brief-facts dd { margin: 0; font-family: var(--mono); font-size: 12px; color: var(--ink); white-space: nowrap
}

.pbody-brief .code { margin: auto 0
}

.code { margin: 0; font-family: var(--mono); font-size: 12.5px; line-height: 1.8; color: var(--ink); white-space: pre; overflow-x: auto; max-width: 100%
}

.code .cy { color: var(--muted)
}

.code .cv { color: var(--ink)
}

.code .ca { color: var(--accent-ink)
}

.code .cc { color: var(--code-faint)
}

.ledger { width: 100%; max-width: 560px; font-family: var(--mono); font-size: 12.5px
}

.ledger .lh { display: flex; justify-content: space-between; gap: 12px; padding-bottom: 10px; border-bottom: 1px solid var(--line); color: var(--ink); flex-wrap: wrap
}

.ledger .lh span { color: var(--label); font-size: 10px; letter-spacing: .12em; text-transform: uppercase
}

.lrow { display: flex; justify-content: space-between; gap: 16px; padding: 10px 0; border-bottom: 1px solid var(--line-soft); flex-wrap: wrap
}

.lrow:last-child { border-bottom: 0
}

.lrow .ln { color: var(--ink)
}

.lrow .ln em { font-style: normal; color: var(--muted); margin-right: 8px
}

.lrow .ld { color: var(--label); text-align: right; flex: 1; min-width: 170px
}

@media (max-width: 420px) {
  .pbar { flex-wrap: wrap; row-gap: 2px; padding-top: 10px; padding-bottom: 10px
  }
  .pname { white-space: normal; overflow: visible; text-overflow: clip
  }
  .pr { white-space: normal
  }
  .ledger .lh { flex-direction: column; gap: 2px
  }
  .lrow { flex-direction: column; gap: 3px
  }
  .lrow .ld { text-align: left; flex: none; min-width: 0; padding-left: 16px
  }
}

.panel-dark { background: var(--panel-deep); border-color: var(--dz-line); color: var(--dz-ink)
}

.panel-dark .pbar { background: rgba(240, 237, 229, .02); border-color: var(--dz-line)
}

.panel-dark .pname { color: var(--dz-ink)
}

.panel-dark .pidx { color: var(--accent-dz)
}

.panel-dark .pr { color: var(--dz-label)
}

.panel-dark .pcap { border-color: var(--dz-line)
}

.panel-dark .prep { color: var(--dz-body)
}

.panel-dark .plab { color: var(--dz-label)
}

.panel-dark .chip { color: var(--accent-dz); border-color: var(--accent-dz-dim)
}

.panel-dark .chip-dot::before { background: var(--accent-dz)
}

.panel-dark :focus-visible, .band-dark :focus-visible { outline-color: var(--accent-dz)
}

@media (min-width: 1024px) {
  html.js .stage .panel { position: absolute; inset: 0; opacity: 0; pointer-events: none; transform: translateY(16px) scale(.99); transition: opacity .28s ease, transform .5s cubic-bezier(.22, 1, .36, 1)
  }
  html.js .stage .panel[data-sizer] { position: relative
  }
  html.js .stage .panel.on { opacity: 1; pointer-events: auto; transform: none; transition: opacity .4s ease .05s, transform .55s cubic-bezier(.22, 1, .36, 1) .05s
  }
  html.js .stage .panel.past { transform: translateY(-14px) scale(.995)
  }
}

@media (max-width: 1023px) {
  .stage { display: grid; gap: 16px
  }
  .panel { box-shadow: var(--sh-rail)
  }
}

html:not(.js) .stage { display: grid; gap: 16px
}
